import dtc; dtc.build(page,E,SITE,SHARE,mlform,NL_URL)
def srcli(t,u): return f'<li><a href="{u}" rel="noopener">{E(t)}</a></li>'
_pd=provinces.load(); seen=set()
def uniq(xs):
    o=[]
    for t,u in xs:
        if u.startswith('http') and u not in seen: seen.add(u); o.append((t,u))
    return o
sb='<h1>Our sources</h1><p class="sub left">Every fact on this site comes from an official page. Here they all are, in one place. Updated Oct 2026.</p><p>We check each link and the amounts on it. Programs change, so always confirm on the official page before you apply. If you spot something out of date, tell us on X: <a href="https://x.com/Gcarsona99" rel="noopener">@Gcarsona99</a>.</p>'
sb+='<h2>Disability Tax Credit (federal)</h2><ul class="srcs">'+''.join(srcli(t,u) for t,u in uniq(dtc.SRC.values()))+'</ul>'
for p in P:
    xs=uniq(p['links'])
    if xs: sb+=f'<h2>{E(p["name"])}</h2><ul class="srcs">'+''.join(srcli(t,u) for t,u in xs)+'</ul>'
for c in provinces.ORDER:
    if c=='bc': continue
    xs=uniq([tuple(l) for q in _pd[c]['programs'] for l in q['links']])
    if xs: sb+=f'<h2>{E(_pd[c]["province"])}</h2><ul class="srcs">'+''.join(srcli(t,u) for t,u in xs)+'</ul>'
page('sources.html','Our sources: official pages behind every fact','Every official government page this site uses, in one list. Updated Oct 2026.',sb)
